INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (32, N'PRJ-2025-0026', 2, N'Sauvegarde des ' + CHAR(10) + N'données VIP sur ' + CHAR(10) + N'OneDrive', N'Configuration, formation et Sauvegarde automatique des ' + CHAR(10) + N'documents utilisateurs via OneDrive. Focus sur DG, DGA, Directeurs, ' + CHAR(10) + N'Chef de Division & de Département.' + CHAR(10) + N'OneDrive est un service de stockage en nuage de Microsoft qui ' + CHAR(10) + N'permet aux utilisateurs de stocker, de partager et d''accéder à leurs ' + CHAR(10) + N'fichiers depuis n''importe quel appareil', 0.0000, NULL, NULL, CONVERT(datetime2(7),N'2025-07-31T00:00:00.0000000',126), 1, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4230500',126), CONVERT(datetime2(7),N'2026-08-26T17:07:58.4230502',126));
INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (33, N'PRJ-2025-0027', 5, N'REIS', N'Interfaçage SmartAcces et REIS TFS pour le filtrage', 0.8000, NULL, NULL, CONVERT(datetime2(7),N'2025-07-31T00:00:00.0000000',126), 2, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4233656',126), CONVERT(datetime2(7),N'2026-08-26T19:58:32.6605833',126));
INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (34, N'PRJ-2025-0028', 6, N'AUTOMATISATION SWIFT', N'il s’agit de permettre que les virements reçus par Swift (XOF et Devises) ' + CHAR(10) + N'soient automatiquement crédités sur les comptes des bénéficiaires dans nos livres', 0.4000, NULL, NULL, CONVERT(datetime2(7),N'2025-08-30T00:00:00.0000000',126), 2, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4237404',126), CONVERT(datetime2(7),N'2026-08-26T19:58:32.6605836',126));
INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (35, N'PRJ-2026-0004', 11, N'SAP BI', N'Outil décisionel permerttant la création de rapport avec SAP ' + CHAR(10) + N'BI', 0.2500, NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4238705',126), CONVERT(datetime2(7),N'2026-08-26T19:58:32.6605841',126));
INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (36, N'PRJ-2025-0029', 4, N'Installation de lien Télécom pour la nouvelle agence Riviera', N'Ce projet vise à installer deux liens télécoms pour cette nouvelle agence', 0.1000, NULL, NULL, CONVERT(datetime2(7),N'2025-09-01T00:00:00.0000000',126), 2, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4240964',126), CONVERT(datetime2(7),N'2026-08-26T19:58:32.6605842',126));
INSERT INTO [dbo].[Projets] ([Id], [Numero], [DomaineProjetId], [Nom], [Description], [TauxAvancement], [DateDebut], [DateFin], [DateEcheance], [StatutProjetId], [Support], [ActeursMetiers], [Contraintes], [Commentaires], [CreatedAt], [UpdatedAt]) VALUES (37, N'PRJ-2025-0030', 4, N'Installation de lien Télécom  MTN pour Banque Privée', N'Ce projet vise à installer un  lien télécom pour la Banque Privée', 0.1000, NULL, NULL, CONVERT(datetime2(7),N'2025-09-01T00:00:00.0000000',126), 2, NULL, NULL, NULL, NULL, CONVERT(datetime2(7),N'2026-08-26T17:07:58.4243470',126), CONVERT(datetime2(7),N'2026-08-26T19:58:32.6605843',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (42, N'INC-2026-0001', CONVERT(datetime2(7),N'2026-01-08T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-01-08T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0001', N'Anomalie critique sur le module de transfert inter-caisse en devise étrangère lors du processus de rappel sous Amplitude. L''opération de rappel génère une erreur bloquante empêchant toute transaction en devises.', 12, 1, N'Blocage total des opérations en devises étrangères au niveau de la caisse. Aucun transfert inter-caisse en devise ne peut être effectué. Impact direct sur les clients souhaitant effectuer des opérations de change ou retrait en devises.', N'Bug identifié dans le module de gestion des devises du Core Banking Amplitude. Dysfonctionnement du processus de rappel des opérations inter-caisses en devise.', 1, N'Escalade de l''incident auprès de la Holding (éditeur Amplitude / SOPRA). Ouverture d''un ticket de support prioritaire auprès de SOPRA pour résolution.', NULL, N'Ticket pris en charge par SOPRA. Suivi en cours de la résolution par l''équipe support de l''éditeur. En attente du correctif applicatif.', 3, 1, N'Mise en place d''un suivi de monitoring des opérations en devise. Planifier des tests de régression sur le module devise après chaque mise à jour Amplitude. Documenter la procédure de contournement en cas de récurrence.', 1, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5481955',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5482266',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (43, N'INC-2026-0002', CONVERT(datetime2(7),N'2026-01-09T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-01-09T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0002', N'Dysfonctionnement critique du module CHEQUES IMPAYES sous SITRACOM. Les chèques impayés traités via SITRACOM ne sont pas correctement reportés dans Amplitude, empêchant la comptabilisation des opérations de retour.', 12, 1, N'Impossibilité de créditer les comptes clients suite au traitement des chèques impayés. Les clients concernés ne voient pas leurs comptes mis à jour. Risque de double traitement ou de pertes financières si les opérations sont relancées manuellement.', N'Bug dans le module d''interface entre SITRACOM et Amplitude. Erreur de traitement lors de la synchronisation des données de chèques impayés entre les deux systèmes.', 1, N'Escalade de l''incident auprès de la Holding pour prise en charge par l''équipe technique Amplitude. Identification des transactions bloquées et isolation des comptes impactés.', NULL, N'En attente de correctif de la part de l''éditeur. Surveillance manuelle des comptes clients affectés.', 1, 3, N'Mettre en place des contrôles automatiques de réconciliation entre SITRACOM et Amplitude. Former les équipes à la détection précoce de ce type d''anomalie.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5483589',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5483590',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (44, N'INC-2026-0003', CONVERT(datetime2(7),N'2026-01-26T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-01-26T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0003', N'Anomalie de comptabilisation des remises de chèques sous Amplitude. Les chèques physiquement remis par les clients et saisis dans le système ne génèrent pas d''écriture comptable de crédit sur le compte du client concerné.', 12, 1, N'Impossibilité de créditer les comptes clients ayant remis des chèques à l''encaissement. Les clients se retrouvent avec un solde non mis à jour malgré la prise en charge physique de leurs chèques. Risque de réclamations clients et d''incidents de trésorerie.', N'Bug dans le module de traitement des remises chèques d''Amplitude. Erreur lors de la génération des écritures comptables automatiques liées aux remises.', 1, N'Escalade de l''incident auprès de la Holding. Identification manuelle des remises de chèques non comptabilisées pour correction ultérieure.', NULL, N'En attente de correctif éditeur. Traitement manuel des remises en attente effectué à titre conservatoire.', 3, 1, N'Mettre en place un contrôle de fin de journée comparant le nombre de remises chèques saisies vs le nombre d''écritures générées. Automatiser une alerte en cas d''écart. Renforcer la procédure de vérification post-saisie par les agents.', 1, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5483838',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5483839',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (45, N'INC-2026-0004', CONVERT(datetime2(7),N'2026-01-27T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-01-27T00:00:00.0000000',126), 2, 4, N'Incident importé INC-2026-0004', N'Interruption totale de la liaison SICA (Système Interbancaire de Compensation Automatisée) entre la BCEAO et la banque. La connexion réseau permettant l''échange des fichiers de compensation interbancaire a été interrompue, bloquant la réception des valeurs compensées.', 12, 1, N'Impossibilité de recevoir les valeurs interbancaires via le réseau SICA. Blocage de toutes les opérations de compensation interbancaire. Impact sur les virements entrants, les chèques présentés à la compensation et les opérations de règlement interbancaire.', N'Panne réseau sur la liaison dédiée SICA reliant la banque au réseau de compensation de la BCEAO. Défaillance du routeur assurant la connectivité avec la BCEAO.', 1, N'Redémarrage du routeur BCEAO par l''équipe infrastructure. Vérification de la connectivité après redémarrage. Rétablissement de la liaison confirmé.', NULL, N'Incident clôturé après rétablissement de la liaison suite au redémarrage du routeur.', 10, 3, N'Mettre en place un monitoring en temps réel de la liaison SICA avec alertes automatiques en cas de coupure. Définir un SLA de rétablissement maximum. Prévoir une procédure de bascule sur liaison de secours. Planifier des tests de continuité de la liaison SICA.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484122',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484123',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (46, N'INC-2026-0005', CONVERT(datetime2(7),N'2026-01-30T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-01-30T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0005', N'Saturation critique de la table d''audit Oracle SYS.AUD$ dans l''environnement Amplitude de la filiale Côte d''Ivoire. L''espace disque alloué à cette table système a atteint sa limite maximale, entraînant le blocage complet du Core Banking.', 12, 1, N'Indisponibilité totale du Core Banking Amplitude pour l''ensemble de la filiale CBI-CI. Aucune opération bancaire ne peut être effectuée : retraits, versements, virements, consultations de compte. Impact majeur sur l''ensemble des agences et des clients.', N'Saturation de la table d''audit Oracle SYS.AUD$ due à l''accumulation excessive de logs d''audit non purgés. Absence de politique de purge automatique ou manuelle des données de cette table système critique.', 1, N'Suppression contrôlée des lignes obsolètes de la table SYS.AUD$ pour libérer l''espace disque. Redémarrage des services Amplitude après l''opération de purge. Vérification du bon fonctionnement du Core Banking post-intervention.', NULL, N'Incident résolu. Surveillance renforcée de l''espace disque post-intervention.', 13, 2, N'Mettre en place un monitoring proactif de la taille de la table SYS.AUD$ avec seuils d''alerte à 70%, 80% et 90% de saturation. Créer un job automatique de purge des logs d''audit anciens de plus de X jours. Définir et documenter une procédure de purge d''urgence. Inclure ce contrôle dans les vérifications journalières de l''équipe DBA.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484397',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484397',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (47, N'INC-2026-0006', CONVERT(datetime2(7),N'2026-02-06T10:00:00.0000000',126), CONVERT(datetime2(7),N'2026-02-06T12:00:00.0000000',126), 2, 4, N'Incident importé INC-2026-0006', N'Défaillance de la communication entre le module SmartApps et le système REIS (Réseau d''Echange Interbancaire de Substitution). Le fichier OUTGO de compensation est arrivé à 10h56 mais les Comptes Rendus d''Opérations (CRO) attendus n''ont pas été produits dans les délais requis.', 12, 1, N'Non-production des CRO 015 nationaux dans les délais réglementaires. Les opérations de retour de compensation restent bloquées à l''état 50 dans le système. Risque de pénalités réglementaires et de non-respect des délais de compensation interbancaire.', N'Lenteur excessive dans le processus de filtrage REIS des opérations de retour de compensation. Goulot d''étranglement dans le traitement du fichier OUTGO par le système REIS, entraînant un dépassement des délais de génération des CRO.', 1, N'Mise à jour manuelle de l''état des virements bloqués de 50 à 52 via requête SQL directe. Génération manuelle des CRO 015 nationaux via l''application SmartApps. Observation continue de l''application pour détecter toute récurrence.', NULL, N'Application sous observation renforcée. Surveillance du traitement des prochains fichiers OUTGO.', 1, 4, N'Assurer et tester régulièrement la fluidité de la communication entre REIS et SmartApps. Mettre en place des alertes de délai sur le traitement des fichiers OUTGO (seuil d''alerte si CRO non générés dans les X minutes suivant réception). Documenter la procédure de correction manuelle SQL pour les équipes d''astreinte. Planifier une revue de performance du filtrage REIS.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484650',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484650',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (48, N'INC-2026-0007', CONVERT(datetime2(7),N'2026-02-19T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-02-19T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0007', N'Bug lors de l''ouverture de la journée de compensation. L''agence du siège n''a pas été cochée/sélectionnée lors du processus d''ouverture de la journée compense, entraînant un blocage du traitement de compensation pour toutes les agences.', 12, 1, N'Journée de compensation non ouverte correctement. Blocage du traitement de toutes les opérations de compensation du jour pour les agences concernées. Risque de non-respect des délais réglementaires de compensation interbancaire.', N'Erreur opérationnelle : l''agence du siège n''a pas été cochée/sélectionnée lors de l''ouverture de la journée de compensation. Absence de contrôle automatique vérifiant l''inclusion de toutes les agences avant validation.', 1, N'Suppression de l''entrée incorrecte dans la table de compensation (corisciv10.bkscomp) via requête SQL. Réouverture correcte de la journée de compensation avec toutes les agences correctement sélectionnées.', NULL, N'RAS - Incident résolu. Journée de compensation rouverte correctement.', 4, 2, N'Mettre en place un contrôle automatique lors de l''ouverture de la journée compense vérifiant que toutes les agences actives sont bien sélectionnées avant de permettre la validation. Créer une liste de contrôle (checklist) obligatoire pour l''opérateur en charge de cette tâche. Ajouter un message d''avertissement si une agence obligatoire est manquante.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484879',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5484880',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (49, N'INC-2026-0008', CONVERT(datetime2(7),N'2026-02-20T00:00:00.0000000',126), NULL, 2, 3, N'Incident importé INC-2026-0008', N'Problème d''authentification sur l''application Carthago utilisée par l''équipe de trésorerie. Les utilisateurs sont dans l''impossibilité de se connecter à l''application, bloquant l''ensemble des activités de gestion de trésorerie.', 12, 1, N'Blocage total des activités de la trésorerie. Impossibilité d''accéder à Carthago pour la gestion des positions de trésorerie, le suivi des opérations interbancaires et la gestion des placements. Impact financier potentiellement significatif en cas de blocage prolongé.', N'Bug applicatif dans le module d''authentification de Carthago. Dysfonctionnement du mécanisme de gestion des sessions ou des credentials d''accès à l''application.', 1, N'Escalade immédiate de l''incident auprès de la Holding pour intervention de l''équipe technique Carthago. Documentation des erreurs d''authentification observées pour faciliter le diagnostic.', NULL, N'RAS - Incident clôturé après intervention de la Holding.', 10, 4, N'Mettre en place un système de monitoring de la disponibilité de Carthago avec alerte immédiate en cas d''indisponibilité. Définir une procédure de continuité des activités de trésorerie en cas de panne de Carthago. Mettre en place des tests d''authentification périodiques automatisés. Prévoir un accès de secours aux données critiques de trésorerie.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485163',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485163',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (50, N'INC-2026-0009', CONVERT(datetime2(7),N'2026-02-24T00:00:00.0000000',126), NULL, 2, 4, N'Incident importé INC-2026-0009', N'Défaillance du service SMTP entraînant la non-réception des tokens d''authentification SMARTBUSINESS par email. Les abonnés au service SMARTBUSINESS ne reçoivent plus les codes OTP nécessaires à la validation de leurs opérations de signature de chèques.', 12, 1, N'Impossibilité pour tous les abonnés SMARTBUSINESS de valider leurs chèques électroniquement. L''ensemble des opérations nécessitant une validation OTP par email est bloqué. Impact sur la clientèle entreprise utilisant SMARTBUSINESS pour la gestion de leurs chèques.', N'Indisponibilité du service SMTP (Simple Mail Transfer Protocol) responsable de l''envoi des emails contenant les tokens OTP. Panne du serveur de messagerie sortante ou blocage par le fournisseur de services email.', 1, N'Escalade de l''incident auprès de la Holding pour intervention sur le service SMTP. Notification aux clients impactés de l''indisponibilité temporaire du service OTP.', NULL, N'RAS - Incident clôturé après rétablissement du service SMTP.', 10, 7, N'Mettre en place un monitoring en temps réel du service SMTP avec alertes automatiques. Prévoir un canal de livraison des OTP alternatif (SMS) en cas d''indisponibilité de l''email. Définir un SLA de disponibilité du service SMTP. Tester régulièrement l''envoi de tokens OTP dans le cadre des contrôles de disponibilité des services.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485433',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485434',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (51, N'INC-2026-0010', CONVERT(datetime2(7),N'2026-03-03T00:00:00.0000000',126), NULL, 3, 4, N'Incident importé INC-2026-0010', N'Rupture de la liaison réseau entre la BCEAO et CORIS Bank CI entraînant la non-réception du fichier INITA (message d''initialisation de la journée de compensation). Sans ce fichier, la journée de compensation ne peut pas être ouverte.', 12, 1, N'Impossibilité d''ouvrir la journée de compensation interbancaire. Toutes les opérations de compensation du jour sont bloquées en attente du rétablissement de la liaison et de la réception du fichier INITA. Risque de non-respect des délais réglementaires de la BCEAO.', N'Indisponibilité du système BCEAO ou de la liaison réseau entre la BCEAO et la banque. Non-émission ou non-réception du fichier INITA nécessaire à l''initialisation de la journée de compensation.', 1, N'Escalade de l''incident auprès de la BCEAO pour rétablissement de la liaison et émission du fichier INITA. Surveillance de la connexion réseau pendant la durée de l''incident.', NULL, N'RAS - Incident clôturé après rétablissement par la BCEAO.', 4, 10, N'Mettre en place un monitoring de la réception du fichier INITA avec alerte automatique si non reçu à l''heure habituelle. Définir une procédure d''escalade rapide vers la BCEAO en cas de non-réception. Documenter les contacts d''urgence BCEAO pour ce type d''incident. Établir un protocole de communication avec la BCEAO sur les délais de résolution.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485714',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485714',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (52, N'INC-2026-0011', CONVERT(datetime2(7),N'2026-03-04T00:00:00.0000000',126), NULL, 3, 4, N'Incident importé INC-2026-0011', N'Rupture de la liaison réseau interne Orange utilisée pour la réception des fichiers ICOMA (fichiers de compensation) depuis la BCEAO. Un bug dans SmartAcces empêche la bascule automatique vers l''opérateur alternatif MTN, bloquant la réception des valeurs BCEAO.', 12, 1, N'Impossibilité de recevoir les valeurs BCEAO via le réseau de compensation. Blocage des opérations d''échange de valeurs interbancaires. Impact sur les virements entrants et les opérations de compensation nécessitant les fichiers ICOMA.', N'Défaillance de la liaison réseau de l''opérateur Orange (liaison dédiée pour la compensation BCEAO). Bug dans SmartAcces empêchant la bascule automatique vers le lien de secours MTN, rendant la redondance réseau inopérante.', 1, N'Escalade de l''incident à la Holding pour la bascule manuelle du lien de compensation vers l''opérateur MTN. Rétablissement de la réception des fichiers ICOMA via MTN.', NULL, N'RAS - Incident clôturé après bascule vers MTN.', 8, 4, N'Corriger le bug dans SmartAcces pour permettre la bascule automatique vers MTN en cas de défaillance d''Orange sans nécessiter l''intervention de la Holding. Tester régulièrement la bascule automatique entre les deux opérateurs. Mettre en place un monitoring de la qualité des deux liaisons réseau. Définir des SLA clairs avec les deux opérateurs réseau.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485980',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5485980',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (53, N'INC-2026-0012', CONVERT(datetime2(7),N'2026-03-05T00:00:00.0000000',126), NULL, 2, 1, N'Incident importé INC-2026-0012', N'Impossibilité de connexion à l''application SMARTRV (Système de Gestion des Remises de Valeurs). Tous les utilisateurs sont bloqués à l''écran d''authentification en raison d''une licence applicative incorrecte ou expirée.', 12, 1, N'Blocage total de l''accès à SMARTRV pour l''ensemble des utilisateurs. Impossibilité de traiter les remises de valeurs, d''effectuer les opérations de rapprochement et de gestion des valeurs via cette application. Impact opérationnel sur les services concernés.', N'Licence applicative SMARTRV incorrecte ou expirée. Le système de gestion des licences rejette les tentatives de connexion suite à une anomalie sur la clé de licence.', 1, N'Escalade de l''incident auprès de la Holding pour renouvellement ou correction de la licence SMARTRV.', NULL, N'Incident clôturé après intervention de la Holding sur la gestion des licences.', 10, 4, N'Mettre en place un suivi et une alerte automatique de l''expiration des licences applicatives (alerte 30, 15 et 7 jours avant expiration). Établir un registre centralisé de toutes les licences logicielles avec leurs dates d''expiration. Désigner un responsable de la gestion des licences logicielles. Créer une procédure de renouvellement anticipé des licences critiques.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486223',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486223',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (54, N'INC-2026-0013', CONVERT(datetime2(7),N'2026-03-05T00:00:00.0000000',126), NULL, 2, 7, N'Incident importé INC-2026-0013', N'Instabilité critique de la plateforme VNEURON impactant l''ensemble des utilisateurs. Trois types de dysfonctionnements sont constatés simultanément : (1) échecs d''authentification récurrents, (2) lenteurs excessives lors de l''accès aux menus et notamment à la fiche client, (3) erreurs systématiques lors du téléchargement de documents.', 12, 1, N'Dégradation majeure de la plateforme VNEURON affectant la productivité de tous les utilisateurs. Accès aux fiches clients perturbé, ralentissant le traitement des demandes clients. Impossible de télécharger les documents nécessaires aux opérations. Risque de non-respect des délais réglementaires liés aux processus utilisant VNEURON.', N'Instabilité de l''infrastructure hébergeant la plateforme VNEURON. Probable dégradation des performances serveur, surcharge du système ou problème de configuration affectant simultanément l''authentification, les performances et la gestion des fichiers.', 1, N'Escalade de l''incident auprès de la Holding pour intervention de l''équipe technique VNEURON. Documentation détaillée des trois types d''anomalies observées pour faciliter le diagnostic.', NULL, N'Incident clôturé après intervention de la Holding.', 10, 7, N'Mettre en place un monitoring de performance de VNEURON avec des indicateurs sur les temps de réponse d''authentification, les temps d''accès aux menus et la performance du téléchargement. Définir des seuils d''alerte pour détecter précocement les dégradations. Planifier des tests de charge réguliers sur la plateforme VNEURON. Mettre en place un tableau de bord de santé de la plateforme.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486506',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486506',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (55, N'INC-2026-0014', CONVERT(datetime2(7),N'2026-03-22T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-03-23T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0014', N'Anomalie bloquante sur le programme de retrait d''espèces sous Amplitude. Un gestionnaire non habilité tente d''exécuter un retrait, ce qui génère une erreur bloquante et empêche le traitement de toutes les opérations de retrait dans le module concerné.', 12, 1, N'Impossibilité d''effectuer des retraits d''espèces pour les clients. Blocage du service de caisse.', N'Tentative d''exécution d''une opération de retrait par un utilisateur ne possedant pas le code du  gestionnaire  du client. Le système Amplitude bloque l''opération et génère une anomalie entraînant le blocage du module,.', 1, N'Escalade de l''incident auprès de la Holding pour correction du dysfonctionnement dans le module retrait d''Amplitude. Identification du gestionnaire non autorisé et vérification de ses droits d''accès.', NULL, N'Incident clôturé après intervention de la Holding.', 4, 6, N'Revoir et corriger la gestion des droits d''accès dans Amplitude pour que le rejet d''une opération non autorisée affiche un message d''erreur clair sans bloquer le module. Auditer régulièrement les habilitations des gestionnaires dans Amplitude. Mettre en place des alertes en cas de tentative d''opération par un utilisateur non habilité. Former les responsables d''agence à la vérification des droits avant attribution de tâches.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486752',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486753',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (56, N'INC-2026-0015', CONVERT(datetime2(7),N'2026-03-22T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-03-22T00:00:00.0000000',126), 2, 2, N'Incident importé INC-2026-0015', N'Bug critique dans le module Amplitude RH bloquant le traitement des salaires du personnel. L''interruption du serveur hébergeant le module RH d''Amplitude empêche l''exécution des traitements de paie, mettant en péril le versement des salaires à la date prévue.', 12, 1, N'Impossibilité de traiter et de virer les salaires du personnel à la date prévue.', N'Interruption du serveur hébergeant le module RH d''Amplitude. Panne matérielle ou logicielle entraînant l''indisponibilité du serveur dédié au traitement des opérations RH et de paie.', 1, N'Escalade urgente de l''incident auprès de la Holding pour redémarrage et remise en service du serveur du module RH Amplitude.', NULL, N'Incident clôturé après intervention de la Holding.', 4, 6, N'Mettre en place une solution de haute disponibilité (cluster ou serveur de secours) pour le module RH d''Amplitude afin d''éviter toute interruption lors des périodes de paie. Planifier les traitements de paie en dehors des heures de pointe et avec une marge temporelle suffisante. Mettre en place un monitoring renforcé du serveur RH pendant les périodes de traitement de paie. Définir une procédure de traitement de secours en cas de panne.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486987',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5486988',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (57, N'INC-2026-0016', CONVERT(datetime2(7),N'2026-03-30T08:00:00.0000000',126), CONVERT(datetime2(7),N'2026-03-30T00:00:00.0000000',126), 2, 5, N'Incident importé INC-2026-0016', N'Problème d''authentification bloquant l''accès à l''application SWIFT Alliance. Les utilisateurs ne peuvent pas se connecter à la plateforme SWIFT, rendant impossible le traitement de tous les messages et opérations financières SWIFT (virements internationaux, lettres de crédit, garanties).', 12, 1, N'Impossibilité de traiter toutes les opérations SWIFT : virements internationaux, opérations de correspondant bancaire, messages financiers. Impact sur les clients ayant des opérations internationales en cours. Risque de retard sur les opérations time-sensitive et de pénalités sur les opérations urgentes.', N'Bug logiciel dans le module d''authentification de SWIFT Alliance. Dysfonctionnement du mécanisme de gestion des credentials,', 1, N'Escalade de l''incident auprès de la Holding pour intervention technique sur SWIFT Alliance.', NULL, N'Incident clôturé après intervention de la Holding.', 8, 8, N'Mettre en place un monitoring de la disponibilité de SWIFT Alliance avec tests d''authentification automatiques périodiques. Définir une procédure de gestion des opérations SWIFT en mode dégradé en cas de panne. Vérifier régulièrement la validité des certificats d''authentification SWIFT avant expiration. Mettre en place une alerte proactive 30 jours avant l''expiration des certificats.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487261',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487262',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (58, N'INC-2026-0017', CONVERT(datetime2(7),N'2026-04-01T08:00:00.0000000',126), CONVERT(datetime2(7),N'2026-04-04T00:00:00.0000000',126), 1, 6, N'Incident importé INC-2026-0017', N'Problème d''alimentation électrique survenu le 13 avril 2026 à l''agence Banque Privée ayant entraîné une rupture de la liaison réseau de l''agence. La coupure électrique a provoqué l''arrêt brutal des équipements réseau actifs (routeur, switch), coupant toute connectivité entre l''agence et le système d''information central. Aucun dégât matériel n''a été constaté sur les équipements IT et réseau à l''issue de l''incident.', 14, 1, N'Interruption totale de l''accès au Core Banking Amplitude et à l''ensemble des applications métier depuis l''agence. Impossibilité pour les agents de traiter les opérations clients (retraits, versements, virements, consultations). Perturbation de l''accueil et du service client pendant la durée de l''incident.', N'Coupure de l''alimentation électrique à l''agence Banque Privée. L''arrêt brutal des équipements réseau (routeur/switch) suite à la perte du courant a entraîné la rupture de la liaison réseau sans endommager physiquement les équipements.', 2, N'Redémarrage des équipements réseau après rétablissement de l''alimentation électrique. Vérification de la connectivité et du bon fonctionnement des applications métier post-redémarrage. Contrôle de l''intégrité des équipements — aucun dégât matériel constaté.', N'Rétablissement de l''alimentation électrique et redémarrage des équipements réseau. Connectivité et services IT restaurés sans remplacement matériel.', N'RAS', 8, 9, N'Équiper l''agence Banque Privée d''un onduleur dédié aux équipements réseau actifs (routeur, switch) pour assurer la continuité de la liaison en cas de coupure secteur. Mettre en place un monitoring de la disponibilité réseau de l''agence avec alerte automatique en cas de coupure. Inclure l''agence Banque Privée dans la cartographie des sites à équiper en protection électrique prioritaire.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487584',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487584',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (59, N'INC-2026-0018', CONVERT(datetime2(7),N'2026-04-13T08:00:00.0000000',126), CONVERT(datetime2(7),N'2026-04-13T00:00:00.0000000',126), 1, 6, N'Incident importé INC-2026-0018', N'Problème d''alimentation électrique survenu le 13 avril 2026 à l''agence Banque Privée ayant entraîné une rupture de la liaison réseau de l''agence. La coupure électrique a provoqué l''arrêt brutal des équipements réseau actifs (routeur, switch), coupant toute connectivité entre l''agence et le système d''information central. Aucun dégât matériel n''a été constaté sur les équipements IT et réseau à l''issue de l''incident.', 9, 1, N'Interruption totale de l''accès au Core Banking Amplitude et à l''ensemble des applications métier depuis l''agence Banque Privée. Impossibilité pour les agents de traiter les opérations clients (retraits, versements, virements, consultations). Perturbation de l''accueil et du service client pendant la durée de l''incident.', N'Coupure de l''alimentation électrique à l''agence Banque Privée. L''arrêt brutal des équipements réseau (routeur/switch) suite à la perte du courant a entraîné la rupture de la liaison réseau sans endommager physiquement les équipements.', 2, N'Redémarrage des équipements réseau après rétablissement de l''alimentation électrique. Vérification de la connectivité et du bon fonctionnement des applications métier post-redémarrage. Contrôle de l''intégrité des équipements — aucun dégât matériel constaté.', N'Rétablissement de l''alimentation électrique et redémarrage des équipements réseau. Connectivité et services IT restaurés sans remplacement matériel.', N'RAS', 8, 9, N'Équiper l''agence Banque Privée d''un onduleur dédié aux équipements réseau actifs (routeur, switch) pour assurer la continuité de la liaison en cas de coupure secteur. Mettre en place un monitoring de la disponibilité réseau de l''agence avec alerte automatique en cas de coupure. Inclure l''agence Banque Privée dans la cartographie des sites à équiper en protection électrique prioritaire.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487885',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5487886',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (60, N'INC-2026-0019', CONVERT(datetime2(7),N'2026-04-18T08:00:00.0000000',126), CONVERT(datetime2(7),N'2026-04-18T00:00:00.0000000',126), 1, 6, N'Incident importé INC-2026-0019', N'Panne électrique majeure survenue le 18 avril 2026 au niveau de l''agence  2-PLTX. La coupure brutale de l''alimentation a provoqué des dommages matériels sur plusieurs équipements IT et électriques du site. La surtension générée lors de la coupure a dépassé les capacités de protection des dispositifs en place, entraînant des dégâts physiques irréversibles sur les équipements concernés et compromettant la disponibilité du site.', 1, 1, N'Indisponibilité des services et équipements hébergés sur le site 2-PLTX. Dommages matériels sur équipements IT et électriques nécessitant remplacement. Risque de perte de données selon les équipements impactés. Interruption potentielle des services dépendants du site 2-PLTX pour l''ensemble des utilisateurs concernés.', N'Panne d''alimentation électrique sur le site 2-PLTX. Coupure ou surtension électrique ayant endommagé les équipements IT et électriques. Protection insuffisante ou dépassée (onduleur, parafoudre) face à l''amplitude de la perturbation électrique.', 1, N'Mise hors tension sécurisée des équipements endommagés. Inventaire complet des équipements IT et électriques impactés. Escalade auprès des prestataires techniques (électricité, maintenance IT) pour évaluation des dégâts. Vérification de l''état des sauvegardes et données critiques hébergées sur le site.', N'Remplacement des équipements IT et électriques endommagés. Remise en service progressive du site après vérification de l''installation électrique.', N'RAS', 8, 9, N'Installer des dispositifs de protection électrique renforcés (onduleurs haute capacité, parafoudres, disjoncteurs différentiels) sur tous les équipements IT critiques du site 2-PLTX. Réaliser un audit complet de l''installation électrique du site avec un électricien certifié. Mettre en place un groupe électrogène de secours dimensionné pour l''ensemble du site. Intégrer le site 2-PLTX dans le Plan de Continuité d''Activité (PCA) avec procédure de bascule en cas de défaillance complète. Planifier des tests de protection électrique semestriels.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5488138',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5488138',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (61, N'INC-2026-0020', CONVERT(datetime2(7),N'2026-04-26T08:00:00.0000000',126), CONVERT(datetime2(7),N'2026-04-30T00:00:00.0000000',126), 1, 6, N'Incident importé INC-2026-0020', N'Panne électrique majeure survenue du 20 avril 2026 au niveau des agences de Koumassi. ayant entraîné une rupture de la liaison réseau de l''agence. La coupure électrique a provoqué l''arrêt brutal des équipements réseau actifs (routeur, switch), coupant toute connectivité entre l''agence et le système d''information central. Aucun dégât matériel n''a été constaté sur les équipements IT et réseau à l''issue de l''incident.', 15, 1, N'Interruption totale de l''accès au Core Banking Amplitude et à l''ensemble des applications métier depuis l''agence. Impossibilité pour les agents de traiter les opérations clients (retraits, versements, virements, consultations). Perturbation de l''accueil et du service client pendant la durée de l''incident.', N'Coupure de l''alimentation électrique. L''arrêt brutal des équipements réseau (routeur/switch) suite à la perte du courant a entraîné la rupture de la liaison réseau sans endommager physiquement les équipements.', 1, N'Redémarrage des équipements réseau après rétablissement de l''alimentation électrique. Vérification de la connectivité et du bon fonctionnement des applications métier post-redémarrage. Contrôle de l''intégrité des équipements — aucun dégât matériel constaté.', N'Rétablissement de l''alimentation électrique et redémarrage des équipements réseau. Connectivité et services IT restaurés sans remplacement matériel.', N'RAS', 8, 9, N'Équiper l''agence Banque Privée d''un onduleur dédié aux équipements réseau actifs (routeur, switch) pour assurer la continuité de la liaison en cas de coupure secteur. Mettre en place un monitoring de la disponibilité réseau de l''agence avec alerte automatique en cas de coupure. Inclure l''agence Banque Privée dans la cartographie des sites à équiper en protection électrique prioritaire.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5488436',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5488437',126));
