INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (84, N'INC-2026-0043', CONVERT(datetime2(7),N'2026-05-26T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-05-26T00:00:00.0000000',126), 2, 2, N'Forcage de la fermeture de journée compense du 18/05/2026', N'Message inhabituel lors de la fermeture de la journée compense du 18/05/2026, ' + CHAR(10) + N'' + CHAR(10) + N'Le système nous demande de forcer la génération car certaines agences ne sont pas fermées', 12, 1, N'Risque de non transmission des valeurs de la compense', N'Certaines agences ne possedaient pas de valeurs à transmettre d’où ce message.', 1, N'1) Vérifer si la compense s''est bien fermée Select * from bkscomp.' + CHAR(10) + N'' + CHAR(10) + N'2) Vérifier s''il existe des valeurs à transmettre sur une agence (015 pour virement et 035 pour cheques)', N'Forcage de la fermeture de la journée compense', N'RAS', 3, 6, N'RAS', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5495529',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5495529',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (85, N'INC-2026-0044', CONVERT(datetime2(7),N'2026-05-26T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-05-26T00:00:00.0000000',126), 2, 4, N'Mauvaises Générations des fichiers LOTS de la compense du 18/05/2026 des virements nationnaux et sous régionnaux', N'Le fichier Lot des virements nationnaux et sous régionnaux  n''a pas correctement été généré,le système affiche 178 virements prêt pour envoi ICOM sur les 950.', 12, 1, N'Risque de non transmission des valeurs de la compense dans les delais.', N'BUG du système  lors de la generation des fichiers LOTS.', 1, N'Escalade de l''incident au niveau du prestataire.', N'1) Reconstitutions du fichier Lot des 950 virements.' + CHAR(10) + N'' + CHAR(10) + N'2) Renvoi du ICOM des 950 virements.' + CHAR(10) + N'' + CHAR(10) + N'3) Faire une demande de retoru de fond pour les valeurs transmises doublement', N'Apporter une mise à jour corrective', 3, 12, N'Verifier la conformité et l''exactitude des fichiers lots générés avant de permettre la transmissions des valeurs en compense.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5495963',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5495963',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (86, N'INC-2026-0045', CONVERT(datetime2(7),N'2026-05-29T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-05-29T00:00:00.0000000',126), 2, 4, N'Générations partielles des fichiers CRO de la compense du 29/05/2026 ', N'Le fichier CRO des effets (046) a été généré partiellement avec 2 lignes manquantes sur un total de 48,  il en est de meme pour le fichier CRO des cheque CRO (035) qui avait un manquant de 13', 12, 1, N'Risque de transmissions incompletes des valeurs', N'La cause est la gestion des Ordres Holdés de REIS. Pendant la génération du CRO si la un cheque est HOLD il n’apparait pas dans le CRO', 1, N'1) Mise à jour des effets à l''état 52 et les cheques à l''état 152 en base de données.' + CHAR(10) + N'' + CHAR(10) + N'2) Renvoi d''un nouvel CRO vers Amplitude.', N'Apporter une mise à jour corrective', N'En observation', 3, 12, N'Faire des tests unitaires avant tout deploiement et Verifier la conformité et l''exactitude des fichiers lots générés avant de permettre la transmissions des valeurs en compense.', 2, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5496381',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5496382',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (87, N'INC-2026-0046', CONVERT(datetime2(7),N'2026-05-29T00:00:00.0000000',126), NULL, 2, 4, N'impression des états au format excel impossible dans SMART', N'L''EDR semble bloqué l''impression des états de smart Acces au format excel', 12, 2, N'Blocage de la célerité des processus', N'Activation d''unEDR sur le serveur', 2, N'Transmission des logs chez le prestataire', N'Desactivation de l''EDR', N'En observation', 3, 12, N'Ajoutez une exclusion dans l’edr ou l’antivirus sur ce dossier c:\smartaccess\interfaces\sortie\', 1, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5497113',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5497115',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (88, N'INC-2026-0047', CONVERT(datetime2(7),N'2026-05-29T00:00:00.0000000',126), NULL, 2, 4, N'Non reception retour ICOMA de la BCEAO', N'Le fihcier ICOMA est toujours en attente depuis l''envoi du message ICOM, il s''agit d''un soucis au niveau de la BCEAO généralisé à tous les confrères', 12, 1, N'Impossible de fermer la compense', N'Dysfonnement du système de SICA UEMOA', 1, N'1) Vérifiaction de la stabilité de la liaison BCEAO.' + CHAR(10) + N'' + CHAR(10) + N'2) Escalde au niveau de la BCEAO', N'En attente du retour de la BCEAO', N'RAS', 5, 14, NULL, 1, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5497605',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5497606',126));
INSERT INTO [dbo].[Incidents] ([Id], [Numero], [DateDeclaration], [DateFin], [TypeIncidentId], [ApplicationId], [Intitule], [Description], [EntiteId], [CriticiteId], [Impact], [Cause], [RisqueId], [ActionsMenees], [Solution], [ActionsEnCours], [ResponsableN1Id], [ResponsableN2Id], [MesuresPreventives], [StatutId], [CreatedAt], [UpdatedAt]) VALUES (89, N'INC-2026-0048', CONVERT(datetime2(7),N'2026-06-04T00:00:00.0000000',126), CONVERT(datetime2(7),N'2026-06-04T00:00:00.0000000',126), 2, 4, N'Transfert partiel des fichiers CRO vers Amplitude', N'Le fichier CRO sont transféré partiellement vers Amplitude', 12, 1, N'Impossible d''effectuer l''integration dans Amplitude', N'Non archivage du répertoire C\ENVOI\', 1, N'1) Transfert manuel du fichier dans le repertoire SCPM/Reception dans Amplitude' + CHAR(10) + N'' + CHAR(10) + N'2) Vider le repertoire C\Envoi', N'Correction du BUG de non archivage du fichier', N'RAS', 5, 12, N'Alertes quand le repertoire C\Envoi est saturé', 1, CONVERT(datetime2(7),N'2026-08-26T12:59:28.5498037',126), CONVERT(datetime2(7),N'2026-08-26T12:59:28.5498037',126));
